import { readFileSync } from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

test.describe("upload vendor documents", () => {
  test("upload a document", { tag: "@DOC-01" }, async ({ apiAs }) => {
    // Arrange: a vendor in draft status owned by the member's tenant
    const member = await apiAs("member");
    const createRes = await member.post("/api/vendors", {
      data: {
        name: uniqueName("Doc Vendor"),
        category: "services",
        contact_email: `billing-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@vendorco.com`,
      },
    });
    expect(createRes.status(), await createRes.text()).toBe(201);
    const vendor = await createRes.json();
    expect(vendor.status, await createRes.text()).toBe("draft");

    // Act: upload the insurance certificate
    const res = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "insurance_certificate",
        file: {
          name: "insurance_certificate.txt",
          mimeType: "text/plain",
          buffer: readFileSync(sample("insurance_certificate.txt")),
        },
      },
    });

    // Assert: response
    const body = await res.text();
    expect(res.status(), body).toBe(201);
    const document = JSON.parse(body);
    expect(document.status, body).toBe("processing");
    expect(document.kind, body).toBe("insurance_certificate");
    expect(document.vendor_id, body).toBe(vendor.id);

    // Assert: audit event recorded for the vendor
    await expect
      .poll(
        async () => {
          const audit = await member.get(`/api/vendors/${vendor.id}/audit`);
          const auditBody = await audit.json();
          return (auditBody.items as { action: string }[]).map((e) => e.action);
        },
        { message: "document.uploaded should appear in the audit trail" },
      )
      .toContain("document.uploaded");
  });
});
